mapper.select:
select sbmci.BROKER_ID brokerId, mci.CUSTOMER_NAME brokerName, sbmci.ACCT_NO accountType, sci.ACCT_NAME accountTypeStr, sbmci.MORE_CONVRATE * 100 tandardRate from STD_BOND_MORE_CONVRATE_INFO sbmci left join mst_customer_info mci on mci.CUSTOMER_ID = sbmci.BROKER_ID left join STL_CAPACCT_INFO sci on sbmci.ACCT_NO = sci.ACCT_NO
sbmci.BROKER_ID = #{brokerId,jdbcType=VARCHAR}
AND sbmci.ACCT_NO = #{accountType,jdbcType=VARCHAR}

mapper.delete:
delete from STD_BOND_MORE_CONVRATE_INFO sbmci
where sbmci.BROKER_ID = #{brokerId,jdbcType=VARCHAR}
and sbmci.ACCT_NO =  #{accountType,jdbcType=VARCHAR}

mapper.select:
select pci.ACCT_NO id , sci.ACCT_NAME text from STL_CAPACCT_INFO sci LEFT JOIN PTL_CAPACCT_INFO pci ON pci.ACCT_NO = sci.ACCT_NO AND pci.CCY = sci.CCY LEFT JOIN(select msd.SALE_DEPID SALE_DEPID,mci.CUSTOMER_ID from mst_sale_department msd left join mst_customer_info mci on mci.CUSTOMER_ID = msd.BROKER_ID where mci.IS_BROKER = 'Y' ) T on T.SALE_DEPID = sci.OWN_DEPT
pci.ACCT_TYPE = 'A07'
and T.CUSTOMER_ID = #{broker,jdbcType=VARCHAR}
